// Generated from services/analysis_execution.py schemas in Python dict order
// (OpenAI strict mode derives `required` from that order). Stage tests check the bytes.
pub fn stage_schema(stage: &str) -> Option<&'static str> {
    Some(match stage {
        "screening" => r#"{"type": "object", "properties": {"domain": {"type": "string", "enum": ["optics", "bio", "ai_ml", "ee", "general"]}, "agent_recommended": {"type": "string", "enum": ["photon", "cell", "neural", "circuit"]}, "relevance_score": {"type": "number", "minimum": 0.0, "maximum": 1.0}, "recipe_applicable": {"type": "boolean"}, "deep_dive_applicable": {"type": "boolean"}, "applicability_reason": {"type": "string"}, "key_topics": {"type": "array", "items": {"type": "string"}}, "methodology_type": {"type": "string", "enum": ["experimental", "computational", "theoretical", "review"]}, "paper_type": {"type": "string", "enum": ["article", "letter", "review"]}, "summary": {"type": "string"}, "is_experimental": {"type": "boolean"}, "has_figures": {"type": "boolean"}, "estimated_complexity": {"type": "string", "enum": ["low", "medium", "high"]}, "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0}}, "required": ["domain", "summary", "relevance_score", "key_topics", "is_experimental", "methodology_type", "recipe_applicable", "deep_dive_applicable"]}"#,
        "citation" => r#"{"type": "object", "properties": {"ref_analyses": {"type": "array", "items": {"type": "object", "properties": {"ref_id": {"type": "string"}, "citation_role": {"type": "string", "enum": ["foundational", "methodological", "comparative", "supporting", "contrasting", "unclear"]}, "evidence_context": {"type": "string"}, "why_cited": {"type": "string"}}, "required": ["ref_id", "citation_role", "why_cited"]}}, "summary": {"type": "string"}, "citation_balance": {"type": "string", "enum": ["balanced", "heavily_reliant", "self_citation_heavy", "diverse"]}, "key_influences": {"type": "array", "items": {"type": "string"}}, "limitations": {"type": "string"}}, "required": ["ref_analyses", "summary", "citation_balance"]}"#,
        "visual" => r#"{"type": "object", "properties": {"figure_count": {"type": "integer"}, "tables_found": {"type": "integer"}, "equations_found": {"type": "integer"}, "diagram_types": {"type": "array", "items": {"type": "string"}}, "quality_summary": {"type": "string"}, "key_findings_from_visuals": {"type": "array", "items": {"type": "string"}}}, "required": ["quality_summary", "key_findings_from_visuals"]}"#,
        "recipe" => r#"{"type": "object", "properties": {"title": {"type": "string"}, "objective": {"type": "string"}, "materials": {"type": "array", "items": {"type": "string"}}, "equipment": {"type": "array", "items": {"type": "string"}}, "parameters": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "value": {"type": "string"}, "unit": {"type": "string"}, "notes": {"type": "string"}, "source_tag": {"type": "string", "enum": ["explicit", "inferred"]}, "evidence_quote": {"type": "string"}, "evidence_page": {"type": "integer"}}, "required": ["name", "value", "source_tag"]}}, "steps": {"type": "array", "items": {"type": "string"}}, "critical_notes": {"type": "array", "items": {"type": "string"}}, "expected_results": {"type": "string"}, "safety_notes": {"type": "string"}, "confidence": {"type": "number"}, "missing_info": {"type": "array", "items": {"type": "string"}}, "reproducibility_score": {"type": "number"}}, "required": ["title", "objective", "parameters", "steps"]}"#,
        "deep_dive" => r#"{"type": "object", "properties": {"problem_definition": {"type": "string"}, "as_is": {"type": "string"}, "to_be": {"type": "string"}, "solution": {"type": "string"}, "method_summary": {"type": "string"}, "key_results": {"type": "string"}, "novelty_assessment": {"type": "string"}, "comparison_to_prior_work": {"type": "string"}, "comparison_scope": {"type": "string", "enum": ["in_paper_only"]}, "strengths": {"type": "array", "items": {"type": "string"}}, "weaknesses": {"type": "array", "items": {"type": "string"}}, "suggested_improvements": {"type": "array", "items": {"type": "string"}}, "follow_up_questions": {"type": "array", "items": {"type": "string"}}, "section_answers": {"type": "array", "maxItems": 12, "items": {"type": "object", "properties": {"section_title": {"type": "string"}, "question": {"type": "string"}, "answer": {"type": "string"}, "explanation": {"type": "string"}, "source_refs": {"type": "array", "maxItems": 4, "items": {"type": "string"}, "minItems": 1}}, "required": ["section_title", "question", "answer", "explanation", "source_refs"]}}, "transfer_checks": {"type": "array", "maxItems": 8, "items": {"type": "object", "properties": {"item": {"type": "string"}, "paper_condition": {"type": "string"}, "condition_basis": {"type": "string", "enum": ["reported", "inferred", "not_reported"]}, "check_before_transfer": {"type": "string"}, "source_refs": {"type": "array", "maxItems": 4, "items": {"type": "string"}}}, "required": ["item", "paper_condition", "condition_basis", "check_before_transfer", "source_refs"]}}, "practical_applications": {"type": "array", "items": {"type": "string"}}}, "required": ["problem_definition", "solution", "method_summary", "key_results", "strengths", "weaknesses", "comparison_scope", "novelty_assessment", "comparison_to_prior_work", "suggested_improvements", "follow_up_questions", "practical_applications", "section_answers", "transfer_checks"]}"#,
        "review_map" => r#"{"type": "object", "properties": {"field_overview": {"type": "string"}, "parts": {"type": "array", "maxItems": 14, "items": {"type": "object", "properties": {"title": {"type": "string"}, "page": {"type": "integer"}, "subfield": {"type": "string"}, "summary": {"type": "string"}, "development": {"type": "string"}, "takeaway": {"type": "string"}}, "required": ["title", "subfield", "summary", "development", "takeaway"]}}, "future_directions": {"type": "array", "maxItems": 8, "items": {"type": "object", "properties": {"need": {"type": "string"}, "research": {"type": "string"}}, "required": ["need", "research"]}}, "reading_paths": {"type": "array", "maxItems": 4, "items": {"type": "object", "properties": {"goal": {"type": "string"}, "order": {"type": "array", "maxItems": 14, "items": {"type": "string"}}}, "required": ["goal", "order"]}}, "part_count": {"type": "integer"}}, "required": ["field_overview", "parts", "future_directions", "reading_paths", "part_count"]}"#,
        "synthesis" => r#"{"type": "object", "properties": {"problem_sentence": {"type": "string"}, "method_sentence": {"type": "string"}, "key_metrics": {"type": "array", "maxItems": 3, "items": {"type": "object", "properties": {"label": {"type": "string"}, "value": {"type": "string"}, "unit": {"type": "string"}, "evidence": {"type": "string"}}, "required": ["label", "value", "unit", "evidence"]}}, "equations": {"type": "array", "maxItems": 5, "items": {"type": "object", "properties": {"latex": {"type": "string"}, "meaning": {"type": "string"}, "symbols": {"type": "array", "maxItems": 4, "items": {"type": "object", "properties": {"symbol": {"type": "string"}, "meaning": {"type": "string"}}, "required": ["symbol", "meaning"]}}, "paper_number": {"type": "string"}}, "required": ["latex", "meaning", "symbols", "paper_number"]}}, "result_figures": {"type": "array", "maxItems": 4, "items": {"type": "object", "properties": {"figure_num": {"type": "string"}, "interpretation": {"type": "string"}}, "required": ["figure_num", "interpretation"]}}, "key_parameters": {"type": "array", "maxItems": 5, "items": {"type": "object", "properties": {"name": {"type": "string"}}, "required": ["name"]}}, "equation_count": {"type": "integer"}}, "required": ["problem_sentence", "method_sentence", "key_metrics", "equations", "result_figures", "key_parameters", "equation_count"]}"#,
        _ => return None,
    })
}
